/**
 * Client configuration snippets for the consumer view. A panel session stores only the
 * project, never the token, so the snippets are generated by the adapter's `clientConfig` with
 * a stand-in token whose secret is a marker, and the marker is then replaced by placeholders:
 * the whole token becomes `<token>` (also inside URLs and base64), and a lone secret, where a
 * snippet splits the token at its colon, becomes `<secret>`.
 */

import type { Adapter, Snippet } from "../adapters/types";

/** Stands for the whole token. */
export const TOKEN_PLACEHOLDER = "<token>";
/** Stands for the part of the token after its colon. */
export const SECRET_PLACEHOLDER = "<secret>";
/** Stands for the base64 encoding of the token (e.g. npm `_auth`). */
export const BASE64_PLACEHOLDER = "<base64 of the token>";

/** A valid-looking `key` secret (32 base62 characters) that never occurs in real output. */
const MARKER = "SREGxPLACEHOLDERxSECRETxMARKERxx";

/** Snippets of an adapter with placeholders instead of the token. */
export function placeholderSnippets(
  adapter: Pick<Adapter, "clientConfig">,
  baseUrl: string,
  login: string,
  packages: string[],
): Snippet[] {
  const token = `${login}:${MARKER}`;
  const replacements: [string, string][] = [
    [token, TOKEN_PLACEHOLDER],
    [encodeURIComponent(token), TOKEN_PLACEHOLDER],
    [btoa(token), BASE64_PLACEHOLDER],
    [MARKER, SECRET_PLACEHOLDER],
  ];
  return adapter.clientConfig(baseUrl, token, packages).map((snippet) => {
    let body = snippet.body;
    for (const [from, to] of replacements) body = body.split(from).join(to);
    return { ...snippet, body };
  });
}
